package fu.fa26.sep490.g58.otcms_be.clinical.service.impl;
import fu.fa26.sep490.g58.otcms_be.clinical.exception.ClinicalOperationException; import fu.fa26.sep490.g58.otcms_be.clinical.model.*; import fu.fa26.sep490.g58.otcms_be.clinical.model.entity.*; import fu.fa26.sep490.g58.otcms_be.clinical.repository.*; import fu.fa26.sep490.g58.otcms_be.clinical.service.*;
import java.time.Clock; import java.time.Instant; import java.util.*; import java.util.regex.Pattern; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class ClinicalExaminationServiceImpl implements ClinicalExaminationService {
 private static final Pattern ICD=Pattern.compile("(?i)^[MS][0-9]{2}(\\.[A-Z0-9]{1,4})?$");
 private final VisitClinicalContextPort visits; private final ClinicalExaminationRepository exams; private final ClinicalDiagnosisRepository diagnoses; private final Clock clock;
 public ClinicalExaminationServiceImpl(VisitClinicalContextPort visits,ClinicalExaminationRepository exams,ClinicalDiagnosisRepository diagnoses,Clock clock){this.visits=visits;this.exams=exams;this.diagnoses=diagnoses;this.clock=clock;}
 @Override @Transactional public ExaminationView saveDraft(ExaminationCommand c){return save(c,ClinicalExaminationStatus.DRAFT);}
 @Override @Transactional public ExaminationView completeExamination(ExaminationCommand c){return save(c,ClinicalExaminationStatus.COMPLETED);}
 private ExaminationView save(ExaminationCommand c,ClinicalExaminationStatus status){var ctx=visits.getVisitContext(c.visitId()); if(ctx==null||ctx.responsibleDoctorId()==null||!ctx.responsibleDoctorId().equals(c.doctorId()))throw new ClinicalOperationException("MSG-14"); if(ctx.status()!=ClinicalVisitStatus.IN_EXAMINATION)throw new ClinicalOperationException("MSG-08"); var ds=c.diagnoses()==null?List.<Diagnosis>of():c.diagnoses(); if(status==ClinicalExaminationStatus.COMPLETED){if(blank(c.reasonForVisit())||blank(c.symptoms())||blank(c.examinationFindings())||ds.stream().filter(d->d!=null&&d.type()==DiagnosisType.PRIMARY).count()!=1||ds.stream().anyMatch(d->d==null||d.type()==null||d.code()==null||!ICD.matcher(d.code()).matches()))throw new ClinicalOperationException("MSG-08");}
 Instant now=clock.instant(); var e=exams.findByVisitId(c.visitId()).orElseGet(()->ClinicalExaminationJpaEntity.create(c.visitId(),c.reasonForVisit(),c.symptoms(),c.examinationFindings(),c.injuryBodySite(),c.injurySide(),c.injuryMechanism(),status,now)); e.update(c.reasonForVisit(),c.symptoms(),c.examinationFindings(),c.injuryBodySite(),c.injurySide(),c.injuryMechanism(),status,now); e=exams.save(e); diagnoses.deleteByExaminationId(e.getId()); for(var d:ds){if(d==null||d.type()==null||d.code()==null||!ICD.matcher(d.code()).matches())throw new ClinicalOperationException("MSG-08");diagnoses.save(new ClinicalDiagnosisJpaEntity(e.getId(),d.code().toUpperCase(Locale.ROOT),d.type()));} return view(e,ds); }
 @Override @Transactional(readOnly=true) public ExaminationView getExamination(UUID visitId,UUID doctorId){var ctx=visits.getVisitContext(visitId);if(!ctx.responsibleDoctorId().equals(doctorId))throw new ClinicalOperationException("MSG-14");return exams.findByVisitId(visitId).map(e->view(e,diagnoses.findByExaminationId(e.getId()).stream().map(d->new Diagnosis(d.getCode(),d.getType())).toList())).orElseThrow(()->new ClinicalOperationException("MSG-04"));}
 private static boolean blank(String s){return s==null||s.isBlank();} private static ExaminationView view(ClinicalExaminationJpaEntity e,List<Diagnosis>d){return new ExaminationView(e.getId(),e.getVisitId(),e.getReasonForVisit(),e.getSymptoms(),e.getExaminationFindings(),e.getInjuryBodySite(),e.getInjurySide(),e.getInjuryMechanism(),e.getStatus(),List.copyOf(d),e.getVersion());}
}
